				return '<li class="lib-row"><div class="lib-main"><b dir="ltr">' + esc(w.lemma) + '</b>' + (m && m.level ? ' <span class="pill">' + m.level + '</span>' : '') + (m ? meaningHtml(m, true) : '<div data-ai-word="' + esc(w.lemma) + '"><button class="link small">اشرح بالـ AI</button></div>')
